#!/bin/zsh
# Generated by Copilot
# Script para configurar todas as variáveis necessárias do projeto Fabrikam Drone Delivery
if [ -z "$ZSH_VERSION" ]; then
  echo -e "${YELLOW}⚠️ Este script foi otimizado para Zsh, mas pode funcionar em outras shells.${NC}"
fi
if ! command -v azd &>/dev/null; then
  echo -e "${RED}❌ O Azure Developer CLI (azd) não está instalado!${NC}"
  exit 1
fi
# Colors
GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
CYAN='\033[0;36m'
NC='\033[0m'

echo -e "${CYAN}=================================================="
echo -e "  🚁 Fabrikam Drone Delivery - Setup Completo"
echo -e "==================================================${NC}"
echo ""

# Mostra variáveis atuais
echo -e "${BLUE}📋 Variáveis atuais:${NC}"
azd env get-values
echo ""
#carrega um ambiente especifico (dev, hml,prd)
environmentName=$(azd env get-values | grep "environmentName=" | cut -d '=' -f2 | tr -d '"')
if [[ -z "$environmentName" ]]; then
  echo -e "${RED}❌ Variável environmentName não definida no azd!${NC}"
  exit 1
fi
envFile="infra/preset/.env.$environmentName"
if [[ ! -f "$envFile" ]]; then
  echo -e "${RED}❌ Arquivo .env não encontrado: $envFile${NC}"
  exit 1
else
  source "$envFile"
  echo -e "${GREEN}✅ Arquivo .env carregado!${NC}"
fi

# Função para definir variável com feedback
set_variable() {
  local name=$1
  local value=$2
  local description=$3
  echo -e "${BLUE}📝 Definindo $name...${NC}"
  if azd env set "$name" "$value"; then
    echo -e "${GREEN}  ✅ $description${NC}"
  else
    echo -e "${RED}  ❌ Erro ao definir $name${NC}"
    return 1
  fi
}
